// ПРОГРАММА ОБУЧЕНИЯ: все острова и уровни по порядку.
// Каждый уровень — название, цель, текст объяснения для озвучки и список рецептов заданий.
// Из этого же файла собирается «ПРОГРАММА.md» (см. tools/make-program.mjs).

import { ORDER, VOWELS, LETTERS, WORDS, STICKERS, TEXTS_SHORT, TEXTS_LONG, WRITE_SENTS } from './data.js';
import { syllables, tokL, tokW } from './tasks.js';

const lv = (title, goal, intro, tasks, extra) => ({ title, goal, intro, tasks, ...extra });
const REV = (title = 'Повторение') => ({ title, review: true });
const pickN = (arr, n) => (arr.length <= n ? arr : Array.from({ length: n }, (_, i) => arr[Math.floor((i * arr.length) / n)]));

// ====================== БУКВЫ И ЧТЕНИЕ ======================
function letterLevel(L, s) {
  const [name, look] = LETTERS[L];
  const sp = 'ЬЪ'.includes(L), v = VOWELS.includes(L);
  const starts = WORDS.filter(x => x.e && x.w[0].toUpperCase() === L).slice(0, 3);
  const has = WORDS.filter(x => x.e && x.w.toUpperCase().includes(L)).slice(0, 3);
  const pics = starts.length ? starts : has;
  const intro = `Это ${sp ? tokL(L) : `буква ${tokL(L)}`}. ${look} ${sp ? '' : v ? 'Это гласная буква: её можно петь. ' : 'Это согласная буква. '}`
    + (pics.length ? `${starts.length ? 'На эту букву начинается' : 'Она есть в словах'}: ${pics.map(x => tokW(x.w)).join(', ')}.` : '');
  const syl = pickN(syllables(s, L), 3);
  const tasks = [['bubL', L, s], ['first', L, s], ['findL', L, s]];
  if (syl.length >= 2) tasks.push(['buildS', syl[0]], ['listenS', syl[1], s], ['fishL', L, s], ['bubS', syl[syl.length - 1], s]);
  else tasks.push(['listenL', L, s], ['fishL', L, s], ['memL', s], ['caseL', s]);
  if (WORDS.some(x => x.st === s && x.e)) tasks.push(['wordpic', s]);
  return lv(`Буква ${L}`, `Узнавать ${sp ? name : 'букву ' + L}${syl.length >= 2 ? ', читать слоги с ней' : ''}`, intro, tasks,
    { show: { letter: L, pics: pics.map(x => [x.e, x.w]) } });
}
function syllableLevel(s, letters) {
  const all = syllables(s).filter(x => letters.some(L => x.includes(L)));
  const y = pickN(all, 5);
  return lv('Читаем слоги', 'Сливать согласную и гласную в слог',
    'Буквы любят дружить. Согласная и гласная встают рядом — получается слог. Читай слог сразу, слитно, как будто поёшь.',
    [['buildS', y[0]], ['listenS', y[1], s], ['bubS', y[2], s], ['pairsSP', s], ['buildS', y[3]], ['listenS', y[4], s], ['sortVC', s]]);
}
const wordsLevel = s => lv('Читаем слова', 'Читать слова из знакомых букв и понимать их',
  'Из слогов получается слово. Прочитай его по слогам, а потом скажи целиком. Что оно значит?',
  [['wordpic', s], ['buildW', s], ['picword', s], ['readW', s], ['missing', s], ['listenW', s], ['pairsWP', s], ['claps']]);
const sentLevelEarly = s => lv('Слова и предложения', 'Читать короткие предложения',
  'Несколько слов встают рядом — получается предложение. Первое слово пишут с большой буквы, а в конце ставят точку.',
  [['wordpic', s], ['sentence', s, 2, 3], ['sentpic', s, 2, 4], ['readS', s, 2, 3], ['buildW', s], ['truefalse', s], ['memWP', s], ['sentence', s, 2, 4]]);

function letterIsland(id, title, letters, s0, can, mid) {
  const L = letters.split(''), s = s0 + L.length;
  const letterLv = L.map((x, i) => letterLevel(x, s0 + i + 1));
  const levels = L.length === 5
    ? [...letterLv.slice(0, 4), REV(), letterLv[4], syllableLevel(s, L), wordsLevel(s), sentLevelEarly(s), REV('Праздник острова')]
    : [...letterLv, mid[0], REV(), mid[1], syllableLevel(s, L), wordsLevel(s), sentLevelEarly(s), REV('Праздник острова')];
  return { id, line: 'R', title, topic: `Буквы ${L.join(', ')}`, can, levels };
}

const wordLv = (title, goal, intro, f, k) => lv(title, goal, intro,
  [['wordpic', 33, f], ['buildW', 33, f], ['picword', 33, f], ['readW', 33, f], ['claps'], ['missing', 33, f], ['listenW', 33, f], [k % 2 ? 'memWP' : 'pairsWP', 33, f]]);
const sentLv = (title, goal, intro, lo, hi, k) => lv(title, goal, intro, k % 2
  ? [['sentpic', 33, lo, hi], ['sentence', 33, lo, hi], ['readS', 33, lo, hi], ['truefalse', 33], ['sentpic', 33, lo, hi], ['sentence', 33, lo, hi], ['wordpic', 33, 'long'], ['truefalse', 33]]
  : [['sentence', 33, lo, hi], ['sentpic', 33, lo, hi], ['readS', 33, lo, hi], ['sentence', 33, lo, hi], ['truefalse', 33], ['sentpic', 33, lo, hi], ['truefalse', 33], ['buildW', 33, 'mid']]);
function textIsland(id, title, set, texts, can) {
  const one = (T, i) => lv(`Рассказ «${T.title}»`, `Прочитать рассказ из ${T.s.length} предложений и ответить на вопросы`,
    `Сегодня читаем рассказ. Он называется: ${T.title}. Читай не спеша. Если трудно — нажми на предложение, и я помогу. Потом я задам вопросы.`,
    [...T.q.map((_, q) => ['story', set, i, q]), ['readT', set, i], ['textSent', set, i], ['textSent', set, i], ...(T.q.length < 4 ? [['truefalse', 33]] : [])]);
  const t = texts.map(one);
  return { id, line: 'R', title, topic: set === 's' ? 'Рассказы из 4 предложений' : 'Рассказы из 7–8 предложений', can,
    levels: [...t.slice(0, 4), REV(), ...t.slice(4, 8), REV('Праздник острова')] };
}

