// ====================== ПИСЬМО ======================
const LOW_DIFF = 'АБЕЁРУФ'; // у этих букв маленькая буква пишется иначе, чем большая
function writePair(A, B) {
  const part = L => [['traceL', L], LOW_DIFF.includes(L) ? ['traceL', L.toLowerCase()] : ['mirror', L], ['copyL', L]];
  return lv(`Пишем ${A} и ${B}`, `Писать печатные буквы ${A} и ${B}`,
    'Сегодня пишем две буквы. Сначала веди пальцем по пунктиру, не спеши. Потом напишешь сам, без пунктира.',
    [...part(A), ...part(B), ['drawL', 'ЬЪЫЙ'.includes(A) ? B : A], ['copyL', LOW_DIFF.includes(B) ? B.toLowerCase() : A]]);
}
function writeWordsUpper(s) {
  const syl = pickN(syllables(s), 2);
  const ws = WORDS.filter(x => x.st <= s && x.st > s - 10 && x.w.length <= 4).slice(0, 2).map(x => x.w.toUpperCase());
  return lv('Пишем слоги и слова', 'Писать слоги и короткие слова печатными буквами',
    'Буквы встают рядом — получается слог, а потом и целое слово. Пиши буквы близко друг к другу, чтобы они не разбежались.',
    [['traceT', syl[0]], ['copyT', syl[0]], ['traceT', ws[0]], ['copyT', ws[0]], ['dictW', s, 'short'], ['traceT', ws[1]], ['copyT', ws[1]]]);
}
function writeIsland(id, title, letters, s, can) {
  const L = letters.split(''), p = [];
  for (let i = 0; i < L.length; i += 2) p.push(writePair(L[i], L[i + 1]));
  return { id, line: 'W', title, topic: `Печатные буквы ${L.join(', ')}`, can,
    levels: [p[0], p[1], p[2], REV(), p[3], p[4], writeWordsUpper(s), REV('Праздник острова')] };
}
const wWords = (title, goal, intro, w) => lv(title, goal, intro,
  [['traceT', w[0][0]], ['copyT', w[0][0]], ['dictT', w[1][0], w[1][1]], ['traceT', w[2][0]], ['copyT', w[2][0]], ['dictT', w[3][0], w[3][1]], ['copyT', w[1][0]]]);
const wSent = (title, goal, intro, i, j, extra) => lv(title, goal, intro,
  [['traceT', WRITE_SENTS[i]], ['copyT', WRITE_SENTS[i]], ['capital', i], ['sentence', 33, 2, 3], ['traceT', WRITE_SENTS[j]], ['copyT', WRITE_SENTS[j]], ['capital', j], ...(extra || [])]);
const shapeLv = (title, goal, intro, a, b, c, d) => lv(title, goal, intro, [['shape', a], ['shape', b], ['shape', a], ['draw', d], ['shape', c], ['shape', b], ['shape', c]]);

