// ====================== ПОРЯДОК ОСТРОВОВ ======================
// Линии чередуются: после букв — счёт, потом письмо и так далее.
const ROUTE = 'r1 m1 w1 r2 m2 w2 r3 m3 r4 w3 m4 r5 m5 r6 w4 m6 r7 w5 x1 r8 m7 w6 x2 r9 m8 w7 x3 r10 m9 w8 x4 r11 m10 x5 r12 d1 x6 m11 d2'.split(' ');
// Какие острова надо пройти раньше: печатную букву пишем после того, как научились её читать, и так далее.
const NEEDS = { w2: ['r2'], w3: ['r4'], w4: ['r6'], w5: ['r7'], w6: ['r7'], w7: ['r7'], w8: ['r7'], x1: ['m6'], d1: ['x5'], m11: ['m8'] };
const byId = Object.fromEntries([...READING, ...WRITING, ...MATH, ...MULT, ...DIVISION].map(i => [i.id, i]));

export const ISLANDS = ROUTE.map((id, n) => ({ ...byId[id], n, sticker: STICKERS[n], needs: NEEDS[id] || [] }));

// Заполняем уровни-повторения заданиями из пройденного.
ISLANDS.forEach((isl, n) => {
  isl.levels.forEach((L, k) => {
    L.id = `${isl.id}-${k + 1}`;
    L.island = n;
    L.k = k;
    if (!L.review) return;
    const last = k === isl.levels.length - 1;
    const prev = isl.levels.slice(last ? 0 : Math.max(0, k - 4), k).filter(x => !x.review);
    const tasks = [];
    for (let i = 0; tasks.length < (last ? 6 : 8) && i < 40; i++) {
      const j = i % prev.length, P = prev[j].tasks;
      const src = P[(k + j * 2 + Math.floor(i / prev.length) * 3) % P.length];
      if (!tasks.some(t => JSON.stringify(t) === JSON.stringify(src))) tasks.push(src);
    }
    // На празднике острова вспоминаем и другие линии: по одному заданию с двух прошлых островов.
    if (last) for (const d of [1, 2]) if (n - d >= 0) { const p = ISLANDS[n - d].levels.filter(x => !x.review); tasks.push(p[p.length - 1].tasks[d]); }
    L.tasks = tasks;
    L.goal = last ? 'Повторить весь остров и получить наклейку' : 'Повторить то, что учили на прошлых уровнях';
    L.intro = last
      ? `Весь остров пройден! Давай вспомним всё, что тут учили. А в конце тебя ждёт наклейка: ${isl.sticker}!`
      : 'Уровень-повторение. Вспомним то, что мы недавно учили. Ты всё это уже умеешь!';
  });
});

export const LEVELS = ISLANDS.flatMap(i => i.levels);
export const levelById = id => LEVELS.find(l => l.id === id);
